var pendingImport=null,pendingImportText='',portabilityError='',portabilityStatus='',portabilityReturnTarget=null,portabilityReadToken=0;
function currentCampaignPayload(){const roles={...(typeof tacticalRoles==='object'?tacticalRoles:{})},positions={...(typeof customPositions==='object'?customPositions:{})},plan=Object.keys(roles).length||Object.keys(positions).length?{lineupPlan:{roles,positions}}:{};return {season,view,playback:{...playbackPrefs},media:{...mediaPrefs},individual:{slot:individualTrainingSlot,focus:individualTrainingFocus},records:{tab:squadTab,filter:recordFilter,sort:recordSort,year:recordYear},...plan};}
function portabilitySummary(summary){const competition=summary.competition==='europe'?'챔피언스리그'+(typeof Europe!=='undefined'&&Europe.stageNames[summary.stage]?' · '+Europe.stageNames[summary.stage]:''):summary.round+'라운드'+(summary.competition==='cup'?' · 컵대회':''),stage=summary.phase==='season-complete'?'시즌 종료':competition+(summary.minute?' · '+summary.minute+'분':'');return '<div class="portable-summary"><strong>'+escapeText(summary.club)+'</strong><span>'+summary.year+'시즌 · '+stage+'</span><dl><div><dt>리그 순위</dt><dd>'+summary.rank+'위</dd></div><div><dt>승점</dt><dd>'+summary.points+'</dd></div><div><dt>구단 자금</dt><dd>£'+Number(summary.balance).toLocaleString('ko-KR')+'</dd></div><div><dt>선수</dt><dd>'+summary.playerCount+'명</dd></div></dl></div>';}
function recoveryIsBlocked(){return typeof saveRecovery!=='undefined'&&saveRecovery.isBlocked();}
function recoveryMarkup(){
 if(typeof saveRecovery==='undefined')return '';
 if(!recoveryIsBlocked()){const archived=saveRecovery.archivedOriginals();return !archived.length?'':'<section><h3>보관한 저장 원본</h3><p class="portable-hint">복원 과정에서 보관한 원본입니다. 현재 구단은 정상적으로 저장됩니다. 필요하면 원본 파일을 받아 보관하세요.</p>'+archived.map((_,index)=>'<button type="button" class="secondary" data-portable="recovery-export" data-recovery-index="'+index+'">보관한 저장 원본 '+(index+1)+' 받기</button>').join('')+'</section>';}
 const originals=saveRecovery.originals(),candidate=saveRecovery.candidate();
 return '<section aria-labelledby="campaign-recovery-title"><h3 id="campaign-recovery-title">저장 복원을 확인해 주세요</h3><p class="portable-error" role="alert">이전 저장을 불러오지 못해 자동 저장을 멈췄습니다. 원본은 그대로 보관하며, 현재 화면의 임시 진행은 저장되지 않습니다.</p><p class="portable-hint">먼저 원본을 받아 보관하고, 아래에서 정상적인 구단 백업을 불러오세요. 새 구단을 시작해도 복원되지 않은 원본은 이 기기에 따로 남깁니다.</p>'+originals.map((_,index)=>'<button type="button" class="secondary" data-portable="recovery-export" data-recovery-index="'+index+'">'+(originals.length===1?'복원되지 않은 저장 원본 받기':'저장 원본 '+(index+1)+' 받기')+'</button>').join('')+(candidate?'<p class="portable-hint">읽을 수 있는 이전 구단 저장도 있습니다. 내용을 확인한 뒤 불러올 수 있어요.</p><button type="button" class="secondary" data-portable="recovery-preview">읽을 수 있는 이전 구단 미리보기</button>':'')+'<button type="button" class="secondary" data-portable="recovery-new">새 구단 시작 · 원본 보관</button></section>';
}
function renderPortability(){
 const dialog=$('portability-dialog');if(!dialog)return;
 let summary='';try{summary=portabilitySummary(CampaignFile.read(CampaignFile.stringify(currentCampaignPayload())).summary);}catch{summary='<p>구단을 저장할 수 없습니다. 현재 경기는 그대로 유지됩니다.</p>';}
 dialog.innerHTML='<div class="portable-head"><div><p class="eyebrow">MY CLUB</p><h2 id="portability-title">저장 · 다른 기기에서 하기</h2></div><button type="button" data-portable="close" class="portable-close" aria-label="저장·설치 닫기">×</button></div><div class="portable-body">'+recoveryMarkup()+'<section><h3>지금 키우는 구단</h3>'+summary+'<button type="button" class="primary" data-portable="export">구단 저장 파일 받기</button><p class="portable-hint">이 파일을 휴대폰으로 옮기고 게임에서 불러오세요. 저장은 기기마다 따로 되며 자동 동기화되지 않습니다.</p></section><section><h3>구단 이어서 하기</h3><label class="portable-file">저장 파일 선택<input id="campaign-import-file" type="file" accept=".json,application/json" aria-label="구단 저장 파일 선택"></label><div id="campaign-import-preview" tabindex="-1" aria-live="polite"></div><p id="campaign-import-error" class="portable-error" role="alert" hidden></p><button type="button" class="primary" data-portable="import" disabled>이 구단으로 불러오기</button><p class="portable-hint">확인한 구단으로 현재 구단을 교체합니다. 교체 직전 구단은 이 기기에 한 번 더 보관합니다.</p><button type="button" class="secondary" data-portable="previous">직전 구단 미리보기</button></section><section><h3>휴대폰 홈 화면에 두기</h3><p id="pwa-state" class="portable-hint" role="status"></p><button id="pwa-install" type="button" class="secondary" hidden>홈 화면에 설치</button><p class="portable-hint">갤럭시 Chrome에서 게임 주소를 열고 ⋮ 메뉴 → 설치 및 바로가기 만들기 → 설치를 선택하세요. 버전에 따라 홈 화면에 추가로 표시됩니다.</p></section><p id="campaign-file-status" role="status"></p></div>';
 $('campaign-import-file').onchange=async e=>{const token=++portabilityReadToken;pendingImport=null;pendingImportText='';portabilityError='';updateImportPreview();const file=e.target.files?.[0];if(!file)return;if(file.size>CampaignFile.maxBytes){portabilityError='저장 파일은 2MB 이하만 불러올 수 있어요.';updateImportPreview();return;}try{const text=await file.text();if(token!==portabilityReadToken||!dialog.open)return;previewCampaignText(text);}catch{if(token!==portabilityReadToken||!dialog.open)return;portabilityError='저장 파일을 읽을 수 없어요. 다른 파일을 선택해 주세요.';updateImportPreview();}};
 dialog.querySelectorAll('[data-portable]').forEach(button=>button.onclick=()=>{const command=button.dataset.portable;if(command==='close')closePortability();if(command==='export')exportCampaign();if(command==='import')applyCampaignImport();if(command==='previous')previewPreviousCampaign();if(command==='recovery-export')exportRecoveryOriginal(Number(button.dataset.recoveryIndex));if(command==='recovery-preview')previewRecoveredCampaign();if(command==='recovery-new')startRecoveryCampaign();});
 if(typeof renderPwaStatus==='function')renderPwaStatus();else $('pwa-state').textContent='인터넷 게임 주소에서 홈 화면 설치를 사용할 수 있습니다.';
 updateImportPreview();
}
function updateImportPreview(){const preview=$('campaign-import-preview'),error=$('campaign-import-error'),button=$('portability-dialog')?.querySelector('[data-portable="import"]');if(preview)preview.innerHTML=pendingImport?portabilitySummary(pendingImport.summary):'';if(error){error.textContent=portabilityError;error.hidden=!portabilityError;}if(button)button.disabled=!pendingImport||!!practiceSession;if($('campaign-file-status'))$('campaign-file-status').textContent=portabilityStatus;}
function previewCampaignText(text){++portabilityReadToken;pendingImport=null;pendingImportText='';portabilityError='';try{pendingImport=CampaignFile.read(text);pendingImportText=text;}catch(error){portabilityError=error.message;}updateImportPreview();if(pendingImport)$('campaign-import-preview')?.focus({preventScroll:true});return pendingImport;}
function previewPreviousCampaign(){try{const raw=localStorage.getItem(storageKey+'-before-import');if(!raw)throw Error('이 기기에 교체 직전 구단이 아직 없습니다.');previewCampaignText(CampaignFile.stringify(JSON.parse(raw)));}catch(error){pendingImport=null;pendingImportText='';portabilityError=error.message;updateImportPreview();}}
function openPortability(){const dialog=$('portability-dialog');if(!dialog||dialog.open)return;portabilityReturnTarget=document.activeElement;++portabilityReadToken;pendingImport=null;pendingImportText='';portabilityError='';portabilityStatus='';if(state&&F.running(state)&&!state.paused){pauseForPlanning();save();render();}renderPortability();dialog.showModal();}
function closePortability(){const dialog=$('portability-dialog');if(dialog?.open)dialog.close();}
function downloadCampaignText(text,filename){const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=filename;document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCampaign(){try{const text=CampaignFile.stringify(currentCampaignPayload());downloadCampaignText(text,'win-again-'+season.year+'season-'+(season.round+1)+'round.json');portabilityStatus='저장 파일을 받았습니다. 휴대폰으로 옮겨 불러오세요.';updateImportPreview();return text;}catch(error){portabilityError='저장 파일을 만들지 못했어요. '+error.message;updateImportPreview();return null;}}
function exportRecoveryOriginal(index=0){try{const entry=(recoveryIsBlocked()?saveRecovery.originals():saveRecovery.archivedOriginals())[index];if(!entry)throw Error('받을 수 있는 저장 원본을 확인해 주세요.');downloadCampaignText(entry.text,'win-again-recovery-original-'+(index+1)+'.json');portabilityStatus='저장 원본을 받았습니다. 복원이 필요할 때까지 이 파일을 보관해 주세요.';updateImportPreview();return entry.text;}catch(error){portabilityError=error.message;updateImportPreview();return null;}}
function previewRecoveredCampaign(){try{const payload=saveRecovery.candidate();if(!payload)throw Error('읽을 수 있는 이전 구단 저장이 없습니다.');return previewCampaignText(CampaignFile.stringify(payload));}catch(error){portabilityError=error.message;updateImportPreview();return null;}}
function startRecoveryCampaign(){if(!recoveryIsBlocked()||practiceSession)return false;if(!window.confirm('복원되지 않은 저장 원본을 이 기기에 따로 보관하고 새 구단을 시작할까요?'))return false;try{previewCampaignText(CampaignFile.stringify({season:S.create(undefined,{suspensions:true,startingClub:true})}));return applyCampaignImport();}catch(error){portabilityError=error.message;updateImportPreview();return false;}}
function storeImportedCampaign(next){
 const before=JSON.stringify(currentCampaignPayload());
 if(typeof saveRecovery!=='undefined')return saveRecovery.replace(next,before);
 // Keep import transactions safe when this UI is exercised independently.
 const recoveryKey=storageKey+'-before-import',previousRecovery=localStorage.getItem(recoveryKey);let recoveryWritten=false;
 try{localStorage.setItem(recoveryKey,before);recoveryWritten=true;localStorage.setItem(storageKey,JSON.stringify(next));}
 catch(error){if(recoveryWritten){try{if(previousRecovery===null)localStorage.removeItem(recoveryKey);else localStorage.setItem(recoveryKey,previousRecovery);}catch{}}throw error;}
}
function applyCampaignImport(){
 if(!pendingImport||practiceSession){if(practiceSession){portabilityError='전술 연습을 마친 뒤 구단을 불러오세요.';updateImportPreview();}return false;}
 let next;try{next=CampaignFile.read(pendingImportText).payload;storeImportedCampaign(next);}catch(error){portabilityError='불러오지 못했어요. 현재 구단은 유지됩니다. '+error.message;updateImportPreview();return false;}
 if(typeof launchHasCampaign!=='undefined')launchHasCampaign=true;
 season=next.season;state=season.match;view=next.view;playbackPrefs=MatchFlow.normalize(next.playback);mediaPrefs={...next.media};individualTrainingSlot=next.individual.slot;individualTrainingFocus=next.individual.focus;individualTrainingNote='';individualTrainingNoteContext=null;trainingCentreFilters={position:'all',query:'',sort:'recommended'};squadTab=next.records.tab;recordFilter=next.records.filter;recordSort=next.records.sort;recordYear=next.records.year;tacticalRoles={...(next.lineupPlan?.roles||{})};customPositions={...(next.lineupPlan?.positions||{})};selected=null;lastEvent=null;lastEventAt=0;rotationNote='';canSave=true;
 matchClock.reset();clearMatchFeedback();cancelMovementPreview();movementElapsed=0;movementStamp=performance.now();movementSeed=null;movementEvent=null;movementEventAge=Infinity;lastMotionFrame=null;if(typeof collapseTacticsBoard==='function')collapseTacticsBoard();else tacticsBoardOpen=false;matchdayTab='live';if(typeof closePlayerDetails==='function')closePlayerDetails();pendingImport=null;pendingImportText='';closePortability();render();notify('구단을 불러왔습니다. '+(!state?'시즌 종료 기록에서 이어갑니다.':F.running(state)?'경기는 저장한 순간에서 일시 정지되어 있습니다.':state.phase==='full'?'저장한 경기 결과를 확인해 주세요.':'저장한 경기 준비에서 이어갑니다.'));return true;
}
document.querySelectorAll('[data-open-portability]').forEach(button=>button.onclick=openPortability);
document.getElementById('portability-dialog')?.addEventListener('close',()=>{++portabilityReadToken;pendingImport=null;pendingImportText='';portabilityReturnTarget?.focus?.({preventScroll:true});});
